"""Adroit pen: maneuver library, multiple-model observer and predictive re-planning on a private copy of the plant.

Control law
-----------
The hand is driven through three-phase "flick and catch" maneuvers
    a(step) = A            for step <  T1
              B            for T1 <= step < T1 + T2
              C            afterwards (a static posture that cradles the pen until the episode ends)
where A, B, C are 24-vectors of servo set points in [-1, 1].  A library of such maneuvers (_LIB_B64, at the end of
this file) was found offline by a quality-diversity random search on a copy of the plant (no learning, no gradients).
Every entry is stored with the pen axis it ends in on the nominal plant (U) and on perturbed plants (UV: 50 % heavier
pen, 30 % less friction, 20 % softer servos, two displaced/turned start poses); a zero row means "pen not held there".

1. Choice at step 0.  The target axis and the pen's start pose are read from the first observation.  Every entry
   gets a pass score per plant variant, s = clip((cos(final axis, target) - 0.95) / C_SAT, 0, 1), and the entries are
   ranked by how many of the variants that cannot be told apart yet would end inside the success cone.  The top
   entries are test-run on the controller's own copy of the plant model (`hl_control.envs.adroit`) from the observed
   pen pose, and scored by the predicted margin over the last TAIL steps (1 = dead centre of the success region,
   0 = on its boundary).
2. Multiple-model observer.  Four copies of the plant (nominal, heavy pen, slippery, weak servos) are fed the applied
   set points step by step; a copy is discarded as soon as its predicted joint angles / pen pose differ from the
   measurement by more than TOL_ID.  The servo gain shows after one step, mass and friction at the first contact.
   (With measurement noise the comparison is skipped and the nominal copy is used.)
3. Re-planning.  The surviving copy is an exact predictor, so the rest of the current maneuver is test-run on it;
   if its predicted margin is below OK, library entries ranked for that plant variant are test-run as continuations
   from the present state (PER_CALL per control step, N_MAX per episode, not after step I_LAST) and the best one is
   adopted.  A plan that still misses gets a wrist trim: from step I_TRIM the two wrist set points turn the whole
   hand by the rotation that carries the predicted final pen axis onto the target, kept only if the predictor
   confirms it.  Once the plan is settled no simulation runs any more and a call costs microseconds.
If no plant copy can be built, the best-ranked entry is simply played back (step 1 without the test runs).

Gains / knobs (PARAMS)
----------------------
C_SAT     cosine band above 0.95 over which a plant variant's pass score saturates (robustness margin wanted)
W_MIN     weight of the worst variant's score in the ranking (ties between entries passing equally many variants)
K_NOM     test runs at step 0 when the pen starts at its usual pose (about 30 ms each); K_SHAKE when it is displaced
OK        predicted margin at which a plan is accepted and the search stops
TAIL      number of final steps over which the predicted margin is taken (hold needs the last 25)
TOL_ID    largest prediction error [rad, m] a plant copy may show and stay a candidate
I_ID      step after which the observer stops waiting for the copies to separate
PER_CALL  test runs per control step while re-planning;  N_MAX  test runs per episode;  I_LAST  last re-planning step
I_TRIM    step from which a wrist trim acts;  N_TRIM  trim iterations;  G_TRIM  fraction of the predicted axis error
          taken out per iteration (1 = full Newton step on the two wrist set points; halved after a rejected step)
"""
import base64
import io

import numpy as np

PARAMS = {"C_SAT": 0.03, "W_MIN": 0.5, "K_NOM": 2, "K_SHAKE": 20, "OK": 0.25, "TAIL": 32, "TOL_ID": 1e-5, "I_ID": 40,
          "PER_CALL": 3, "N_MAX": 26, "I_LAST": 70, "I_TRIM": 120, "N_TRIM": 3, "G_TRIM": 1.0}

_CENTER = np.array([0.0, -0.2, 0.25])   # where the pen's centre has to stay
_N = 200                                # control steps per episode
# plant variants the observer tells apart: (pen mass scale, friction scale, servo gain scale, column of UV or -1)
_VARIANTS = ((1.0, 1.0, 1.0, -1), (1.5, 1.0, 1.0, 0), (1.0, 0.7, 1.0, 1), (1.0, 1.0, 0.8, 2))
# the two displaced start poses of UV columns 3 and 4, as (dx / 0.015 m, dy / 0.015 m, yaw / 0.3 rad)
_TEST_POSES = np.array([[0.8, -0.667, 0.667], [-0.667, 0.8, -0.733]])
_POSE_SCALE = np.array([0.015, 0.015, 0.3])


def _table(p):
    """Set points of maneuver p for every control step, shape (200, 24)."""
    t1, t2 = int(round(p[72])), int(round(p[73]))
    tab = np.empty((_N, 24))
    tab[:] = np.clip(p[48:72], -1.0, 1.0)
    tab[: min(t1 + t2, _N)] = np.clip(p[24:48], -1.0, 1.0)
    tab[: min(t1, _N)] = np.clip(p[0:24], -1.0, 1.0)
    return tab


def _quat_z_to(t):
    """Quaternion that turns the z axis onto the unit vector t."""
    q = np.array([1.0 + t[2], -t[1], t[0], 0.0])
    nq = np.linalg.norm(q)
    return q / nq if nq > 1e-9 else np.array([0.0, 1.0, 0.0, 0.0])


class _Plant:
    """Private copy of the plant, stepped exactly like the environment (5 physics steps per control step)."""

    def __init__(self, mass, fric, gain):
        from hl_control.envs import adroit   # the plant's own model; its MuJoCo binding steps the copies
        self.mj = adroit.mujoco
        self.env = adroit.AdroitEnv(adroit.AdroitConfig(task="pen", object_mass_scale=mass, friction_scale=fric,
                                                        actuator_gain_scale=gain))
        self.m = self.env.model
        self.live = self.mj.MjData(self.m)   # follows the real plant step by step
        self.work = self.mj.MjData(self.m)   # scratch state for test runs
        self.final = None                    # (final pen axis, world axes of the wrist joints) of the last test run
        s = self.env.sim
        self.obj, self.top, self.bot, self.tar = s.obj_body_id, s.obj_t_site_id, s.obj_b_site_id, s.target_obj_body_id
        self.mean, self.half = self.env.ctrl_mean.copy(), self.env.ctrl_half_range.copy()

    def start(self, init, target):
        """Put the live state at the start of an episode: pen displaced by init = (dx, dy, yaw), target as observed."""
        mj, m, d = self.mj, self.m, self.live
        m.body_quat[self.tar] = _quat_z_to(target)       # the target pen is a collision body: place it as observed
        mj.mj_resetData(m, d)
        d.qpos[26] += init[0]
        d.qpos[25] += init[1]
        d.qpos[27] -= init[2]
        mj.mj_forward(m, d)

    def follow(self, action):
        """Advance the live state by one control step; return the predicted measurement (joints, pen centre, axis)."""
        d = self.live
        d.ctrl[:] = self.mean + action * self.half
        self.mj.mj_step(self.m, d, 5)
        ax = d.site_xpos[self.top] - d.site_xpos[self.bot]
        return np.concatenate([d.qpos[:24], d.xpos[self.obj], ax / np.linalg.norm(ax)])

    def margin(self, tab, i0, target, tail):
        """Test run from the live state at control step i0 with set-point table tab; worst success margin over the
        last `tail` steps: min of (cos - 0.95)/0.05 and (0.075 - offset)/0.075, positive when hold is predicted."""
        mj, m, d = self.mj, self.m, self.work
        mj.mj_copyData(d, m, self.live)
        worst = np.inf
        self.final = None
        for i in range(i0, _N):
            d.ctrl[:] = self.mean + tab[i] * self.half
            mj.mj_step(m, d, 5)
            off = d.xpos[self.obj] - _CENTER
            if off[2] < -0.1:                # the pen is falling out of the hand
                return -10.0
            if i >= _N - tail:
                ax = d.site_xpos[self.top] - d.site_xpos[self.bot]
                c = float(ax @ target) / float(np.linalg.norm(ax))
                worst = min(worst, (c - 0.95) / 0.05, (0.075 - float(np.linalg.norm(off))) / 0.075)
                if worst < -3.0:
                    return worst
        ax = d.site_xpos[self.top] - d.site_xpos[self.bot]
        self.final = (ax / np.linalg.norm(ax), d.xaxis[0:2].copy())   # final pen axis, world axes of WRJ1 and WRJ0
        return worst


_plants = None   # the four plant copies, built at the first call
_S = None        # per-episode state: plan ("tab"), its predicted margin ("m"), observer phase, candidate queue


def _begin(o):
    """Step 0: choose a maneuver from the first observation and set up the observer."""
    global _plants, _S
    if _plants is None:
        _plants = [_Plant(v[0], v[1], v[2]) for v in _VARIANTS]
    t = o[36:39] / max(np.linalg.norm(o[36:39]), 1e-9)
    init = np.array([o[24], o[25] + 0.2, np.arctan2(o[34], o[33])])
    # The hand always starts at zero, so the joint channels of the first observation show the sensor noise level;
    # a start pose within that noise of the usual one is taken to be the usual one.
    sig = float(np.sqrt(np.mean(o[0:24] ** 2)))
    noisy = sig > 1e-9
    usual = bool(np.all(np.abs(init) < max(3.5 * sig, 1e-6)))
    if usual:
        init[:] = 0.0
    sat = PARAMS["C_SAT"]
    cosn = _U @ t
    s_nom = np.clip((cosn - 0.95) / sat, 0.0, 1.0)              # nominal plant
    s_var = np.clip((_UV @ t - 0.95) / sat, 0.0, 1.0)           # heavy, slippery, weak, displaced a, displaced b
    if usual:
        s = np.concatenate([s_nom[:, None], s_var[:, :2]], axis=1)   # weak servos show after one step: not ranked here
        rank = s.sum(axis=1) + PARAMS["W_MIN"] * s.min(axis=1) + 0.25 * s_var[:, 2]
        k_max = int(PARAMS["K_NOM"])
    else:
        # displaced pen: prefer entries whose outcome survived a similar displacement in the offline test
        w = 2.0 * np.exp(-0.5 * np.sum((_TEST_POSES - init / _POSE_SCALE) ** 2, axis=1))
        rank = s_nom * (1.0 + s_var[:, 3:] @ w) + 0.25 * s_var[:, :3].sum(axis=1)
        k_max = int(PARAMS["K_SHAKE"])
    rank = rank + 1e-3 * cosn                                    # tie-break: closest nominal final axis
    order = list(np.argsort(-rank))
    nominal = _plants[0]
    nominal.start(init, t)
    best_tab, best_m, best_fin, tried = None, -np.inf, None, 0
    while order and tried < k_max:
        tab = _table(_P[order.pop(0)])
        mg = nominal.margin(tab, 0, t, int(PARAMS["TAIL"]))
        tried += 1
        if mg > best_m:
            best_tab, best_m, best_fin = tab, mg, nominal.final
        if mg > PARAMS["OK"]:
            break
    _S = {"t": t, "tab": best_tab, "m": best_m, "fin": best_fin, "tries": tried, "queue": order, "s_nom": s_nom,
          "s_var": s_var, "last": None}
    if noisy:                     # no exact comparison possible: trust the nominal copy
        _S.update(phase="search", v=0, alive=[0])
    else:
        for pl in _plants[1:]:
            pl.start(init, t)
        _S.update(phase="identify", v=None, alive=[0, 1, 2, 3])


def _observe(step, o):
    """Steps >= 1: prune the plant copies against the measurement, then re-plan on the survivor if needed."""
    S = _S
    if S["phase"] == "done":
        return
    if S["phase"] == "identify":
        z = np.concatenate([o[0:24], o[24:27], o[33:36]])
        S["alive"] = [v for v in S["alive"] if np.abs(_plants[v].follow(S["last"]) - z).max() < PARAMS["TOL_ID"]]
        if len(S["alive"]) != 1:
            if len(S["alive"]) == 0 or step >= PARAMS["I_ID"]:
                S["phase"] = "done"       # unknown plant, or copies that never separate: keep the plan
            return
        v = S["alive"][0]
        S.update(phase="search", v=v)
        if v != 0:                        # the plan was chosen on the nominal copy: predict it on the plant that is there
            S["m"] = _plants[v].margin(S["tab"], step, S["t"], int(PARAMS["TAIL"]))
            S["fin"] = _plants[v].final
            S["tries"] += 1
            col = _VARIANTS[v][3]
            rank = S["s_var"][:, col] + 0.3 * S["s_nom"] + 1e-3 * (_UV[:, col] @ S["t"])
            S["queue"] = list(np.argsort(-rank))
    else:
        _plants[S["v"]].follow(S["last"])  # keep the predictor at the present state
    pl = _plants[S["v"]]
    if S["m"] >= PARAMS["OK"] or step > PARAMS["I_LAST"] or S["tries"] >= PARAMS["N_MAX"] or not S["queue"]:
        if S["m"] < PARAMS["OK"]:
            _trim(pl, step)
        S["phase"] = "done"
        return
    for _ in range(int(PARAMS["PER_CALL"])):
        if not S["queue"]:
            break
        tab = S["tab"].copy()
        tab[step:] = _table(_P[S["queue"].pop(0)])[step:]
        mg = pl.margin(tab, step, S["t"], int(PARAMS["TAIL"]))
        S["tries"] += 1
        if mg > S["m"]:
            S["tab"], S["m"], S["fin"] = tab, mg, pl.final
        if S["m"] >= PARAMS["OK"]:
            break


def _trim(pl, step):
    """Model-predictive wrist trim of a plan that still misses: late in the episode, turn the hand with the two wrist
    set points by the rotation that carries the predicted final pen axis onto the target (its components about the
    two wrist axes); keep the change only if the predictor confirms a better margin."""
    S = _S
    k0 = max(step, int(PARAMS["I_TRIM"]))
    gain = PARAMS["G_TRIM"]
    for _ in range(int(PARAMS["N_TRIM"])):
        if S["fin"] is None or k0 > 150:
            return
        u, axes = S["fin"]
        w = np.cross(u, S["t"])
        sn = float(np.linalg.norm(w))
        if sn < 1e-6:
            return
        w *= np.arctan2(sn, float(u @ S["t"])) / sn          # rotation vector from the predicted axis to the target
        tab = S["tab"].copy()
        tab[k0:, 0:2] = np.clip(tab[k0:, 0:2] + gain * (axes @ w) / pl.half[0:2], -1.0, 1.0)
        mg = pl.margin(tab, step, S["t"], int(PARAMS["TAIL"]))
        S["tries"] += 1
        if mg > S["m"]:
            S["tab"], S["m"], S["fin"] = tab, mg, pl.final
        else:
            gain *= 0.5                   # not confirmed: retry with half the step


def _fallback(o):
    """No usable plant copy: take the entry whose stored final axes fit the target best and play it open loop."""
    global _S
    t = o[36:39] / max(np.linalg.norm(o[36:39]), 1e-9)
    s = np.clip((_U @ t - 0.95) / PARAMS["C_SAT"], 0.0, 1.0)[:, None]
    s = np.concatenate([s, np.clip((_UV[:, :3] @ t - 0.95) / PARAMS["C_SAT"], 0.0, 1.0)], axis=1)
    rank = s.sum(axis=1) + PARAMS["W_MIN"] * s.min(axis=1) + 1e-3 * (_U @ t)
    _S = {"tab": _table(_P[int(np.argmax(rank))]), "phase": "done", "last": None}


def controller(obs: dict) -> np.ndarray:
    n = int(obs["action_dim"])
    if n != 24:                           # not the pen task: nothing sensible to do
        return np.zeros(n)
    step = int(obs["step"])
    o = np.asarray(obs["observation"], dtype=float)
    if step == 0 or _S is None:
        try:
            _begin(o)
        except Exception:
            _fallback(o)
    else:
        try:
            _observe(step, o)
        except Exception:
            _S["phase"] = "done"          # keep the current plan
    a = _S["tab"][min(step, _N - 1)].copy()
    _S["last"] = a
    return a


